  11 export struct BaseNetWorkListView {
  12   /**
  13    * 当前列表请求 UI 状态
  14    */
  15   @Param
  16   uiState: BaseNetWorkListUiState = BaseNetWorkListUiState.LOADING;
  17   /**
  18    * 错误状态下的重试回调
  19    */
  20   @Param
  21   onRetry: () => void = () => {
  22   };
  23   /**
  24    * 自定义加载内容
  25    */
  26   @BuilderParam
  27   loadingBuilder: CustomBuilder;
  28   /**
  29    * 自定义错误内容
  30    */
  31   @BuilderParam
  32   errorBuilder: CustomBuilder;
  33   /**
  34    * 自定义空数据内容
  35    */
  36   @BuilderParam
  37   emptyBuilder: CustomBuilder;
  38   /**
  39    * 成功状态下渲染内容
  40    */
  41   @BuilderParam
  42   content: CustomBuilder;
  43 
  44   /**
  45    * 默认加载视图
  46    * @returns {void} 无返回值
  47    */
  48   @Builder
  49   buildDefaultLoading(): void {
  50     PageLoading();
  51   }
  52 
  53   /**
  54    * 默认错误视图
  55    * @returns {void} 无返回值
  56    */
  57   @Builder
  58   buildDefaultError(): void {
  59     EmptyNetwork({
  60       onAction: this.onRetry
  61     });
  62   }
  63 
  64   /**
  65    * 默认空数据视图
  66    * @returns {void} 无返回值
  67    */
  68   @Builder
  69   buildDefaultEmpty(): void {
  70     EmptyData();
  71   }
  72 
  73   /**
  74    * 渲染列表请求状态视图
  75    * @returns {void} 无返回值
  76    */
  77   build() {
  78     Stack() {
  79       Column() {
  80         if (this.loadingBuilder) {
  81           this.loadingBuilder();
  82         } else {
  83           this.buildDefaultLoading();
  84         }
  85       }
  86       .opacity(this.uiState === BaseNetWorkListUiState.LOADING ? 1 : 0)
  87       .animation({ duration: 200, curve: Curve.EaseInOut });
  88 
  89       Column() {
  90         if (this.errorBuilder) {
  91           this.errorBuilder();
  92         } else {
  93           this.buildDefaultError();
  94         }
  95       }
  96       .opacity(this.uiState === BaseNetWorkListUiState.ERROR ? 1 : 0)
  97       .animation({ duration: 200, curve: Curve.EaseInOut });
  98 
  99       Column() {
 100         if (this.emptyBuilder) {
 101           this.emptyBuilder();
 102         } else {
 103           this.buildDefaultEmpty();
 104         }
 105       }
 106       .opacity(this.uiState === BaseNetWorkListUiState.EMPTY ? 1 : 0)
 107       .animation({ duration: 200, curve: Curve.EaseInOut });
 108 
 109       Column() {
 110         if (this.content) {
 111           this.content();
 112         }
 113       }
 114       .opacity(this.uiState === BaseNetWorkListUiState.LOADING
 115         || this.uiState === BaseNetWorkListUiState.ERROR
 116         || this.uiState === BaseNetWorkListUiState.EMPTY ? 0 : 1)
 117       .animation({ duration: 200, curve: Curve.EaseInOut });
 118     }
 119   }
 120 }"}
