{"Path":"feature/user/src/main/ets/view/AddressListPage.ets","NumberedSource":"   1 import { BaseNetWorkListUiState } from "base";
   2 import { ColumnBase, ColumnStart, P100 } from "designsystem";
   3 import { Address } from "model";
   4 import { UserNavigator } from "navigation";
   5 import { getWindowSafeAreaState, WindowSafeAreaState } from "state";
   6 import {
   7   AddressActionButton,
   8   AddressCard,
   9   AppBottomButton,
  10   AppNavDestination,
  11   BaseNetWorkListView,
  12   RefreshLayout
  13 } from "ui";
  14 import AddressListViewModel from "../viewmodel/AddressListViewModel";
  15 
  16 /**
  17  * @file 地址列表页面视图
  18  * @author Joker.X
  19  */
  20 @ComponentV2
  21 export struct AddressListPage {
  22   /**
  23    * 地址列表页面 ViewModel
  24    */
  25   @Local
  26   private vm: AddressListViewModel = new AddressListViewModel();
  27   /**
  28    * 列表滚动控制器，用于刷新同步
  29    */
  30   private listScroller: Scroller = new Scroller();
  31   /**
  32    * 当前窗口安全区状态
  33    */
  34   @Param
  35   windowSafeAreaState: WindowSafeAreaState = getWindowSafeAreaState();
  36 
  37   /**
  38    * 构建地址列表页面
  39    * @returns {void} 无返回值
  40    */
  41   build() {
  42     AppNavDestination({
  43       title: $r("app.string.address_list_title"),
  44       viewModel: this.vm,
  45       paddingValue: {
  46         top: this.windowSafeAreaState.topInset,
  47         left: this.windowSafeAreaState.leftInset,
  48         right: this.windowSafeAreaState.rightInset,
  49       }
  50     }) {
  51       ColumnStart({ fillMaxSize: true }) {
  52         BaseNetWorkListView({
  53           uiState: this.vm.uiState,
  54           onRetry: (): void => this.vm.retryRequest(),
  55           content: (): void => this.AddressListContent()
  56         }).layoutWeight(1);
  57 
  58         if (this.vm.shouldShowBottomButton()) {
  59           AppBottomButton({
  60             text: $r("app.string.address_add_new"),
  61             onTap: (): void => UserNavigator.toAddressDetail()
  62           });
  63         }
  64       }
  65     }
  66   }
  67 
  68   /**
  69    * 地址列表页面内容视图
  70    * @returns {void} 无返回值
  71    */
  72   @Builder
  73   private AddressListContent() {
  74     RefreshLayout({
  75       loading: this.vm.isLoading,
  76       isEnableSlideUp: this.vm.isEnableSlideUp,
  77       scroller: this.listScroller,
  78       onRefresh: (direction): void => this.vm.onRefreshDirection(direction),
  79     }) {
  80       List({ space: 12, scroller: this.listScroller }) {
  81         ForEach(this.vm.listData, (item: Address): void => {
  82           ListItem() {
  83             this.AddressListItem(item);
  84           }
  85         }, (item: Address): string => `${item.id}`);
  86       }
  87       .width(P100)
  88       .height(P100)
  89       .padding($r("app.float.space_padding_medium"));
  90     }
  91   }
  92 
  93   /**
  94    * 渲染地址列表项
  95    * @param {Address} item - 地址数据
  96    * @returns {void} 无返回值
  97    */
  98   @Builder
  99   private AddressListItem(item: Address): void {
 100     AddressCard({
 101       address: item,
 102       onTap: (): void => this.vm.onAddressClick(item),
 103       actionSlot: (): void => this.AddressActionSlot(item)
 104     });
 105   }
 106 
 107   /**
 108    * 渲染地址操作区域
 109    * @param {Address} item - 地址数据
 110    * @returns {void} 无返回值
 111    */
 112   @Builder
 113   private AddressActionSlot(item: Address): void {
 114     Row({ space: 8 }) {
 115       AddressActionButton({
 116         iconResId: $r("app.media.ic_edit_fill"),
 117         onTap: (): void => this.vm.onEditAddress(item.id)
 118       });
 119 
 120       AddressActionButton({
 121         iconResId: $r("app.media.ic_delete_fill"),
 122         onTap: (): void => this.vm.onDeleteAddress(item.id)
 123       });
 124     }
 125   }
 126 }"}
